import { X } from "lucide-react";
import PropTypes from "prop-types";
import { UploadIcon, ImageIcon } from "../icons/index.jsx";
import { useCallback, useMemo, useState, useEffect, useRef } from "react";

const FileUpload = ({
  label = "File Upload",
  value,
  id,
  onChange,
  accept = "image/*",
  isDisabled = false,
  showPreview = true,
  maxSizeMB = 5,
  ...rest
}) => {
  const [previewUrl, setPreviewUrl] = useState(null);
  const [error, setError] = useState("");
  const [isDragging, setIsDragging] = useState(false);
  const dragCounter = useRef(0);

  useEffect(() => {
    if (!value) {
      setPreviewUrl(null);
      return;
    }

    if (value instanceof File) {
      const objectUrl = URL.createObjectURL(value);
      setPreviewUrl(objectUrl);
      return () => URL.revokeObjectURL(objectUrl);
    }

    if (value?.url) {
      setPreviewUrl(value.url);
    }
  }, [value]);

  const displayedName = useMemo(() => {
    if (!value) return null;
    if (value instanceof File) return value.name;
    if (value?.originalname) return value.originalname;
    return "File uploaded";
  }, [value]);

  const isImage = useMemo(() => {
    if (!value) return false;

    if (value instanceof File) {
      return value.type.startsWith("image/");
    }

    if (value?.originalname) {
      return /\.(jpg|jpeg|png|gif|webp|svg)$/i.test(value.originalname);
    }

    return false;
  }, [value]);

  const validateFile = useCallback(
    (file) => {
      const fileSizeMB = file.size / (1024 * 1024);

      if (fileSizeMB > maxSizeMB) {
        setError(`File size must be less than ${maxSizeMB}MB`);
        return false;
      }

      if (accept && accept !== "*") {
        const acceptedTypes = accept.split(",").map((type) => type.trim());
        const fileType = file.type;
        const fileExtension = "." + file.name.split(".").pop();

        const isAccepted = acceptedTypes.some((acceptType) => {
          if (acceptType.endsWith("/*")) {
            return fileType.startsWith(acceptType.replace("/*", ""));
          }
          return acceptType === fileType || acceptType === fileExtension;
        });

        if (!isAccepted) {
          setError(`File type not accepted. Accepted: ${accept}`);
          return false;
        }
      }

      setError("");
      return true;
    },
    [accept, maxSizeMB],
  );

  const handleFileChange = useCallback(
    (e) => {
      const file = e.target.files?.[0];
      if (!file) return;

      if (validateFile(file)) {
        onChange({ name: e.target.name, value: file });
      }
    },
    [onChange, validateFile],
  );

  const handleRemove = useCallback(
    (e) => {
      e.stopPropagation();
      setPreviewUrl(null);
      setError("");
      onChange({ name: id, value: null });

      const input = document.getElementById(id);
      if (input) input.value = "";
    },
    [onChange, id],
  );

  const handleDragEnter = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();

    dragCounter.current++;
    if (e.dataTransfer.items && e.dataTransfer.items.length > 0) {
      setIsDragging(true);
    }
  }, []);

  const handleDragLeave = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();

    dragCounter.current--;
    if (dragCounter.current === 0) {
      setIsDragging(false);
    }
  }, []);

  const handleDragOver = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const handleDrop = useCallback(
    (e) => {
      e.preventDefault();
      e.stopPropagation();

      setIsDragging(false);
      dragCounter.current = 0;

      if (isDisabled) return;

      const files = e.dataTransfer.files;
      if (files && files.length > 0) {
        const file = files[0];
        if (validateFile(file)) {
          onChange({ name: id, value: file });
        }
      }
    },
    [isDisabled, onChange, id, validateFile],
  );

  return (
    <div className="space-y-3">
      <div
        onDragEnter={handleDragEnter}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        className={`
          relative border-2 border-dashed rounded-xl 
          transition-all duration-300 ease-in-out
          ${
            isDisabled
              ? "opacity-50 cursor-not-allowed bg-default-50"
              : "cursor-pointer hover:border-primary-400"
          }
          ${
            isDragging && !isDisabled
              ? "border-primary-500 bg-primary-50 scale-[1.02] shadow-lg"
              : error
                ? "border-danger bg-danger-50/30"
                : value
                  ? "border-success-300 bg-success-50/30"
                  : "border-default-300 bg-white"
          }
        `}
      >
        <label
          htmlFor={id}
          className={`
            relative block w-full p-6
            ${isDisabled ? "cursor-not-allowed" : "cursor-pointer"}
          `}
        >
          {isDragging && !isDisabled && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-white/90 rounded-xl z-10 pointer-events-none">
              <UploadIcon className="w-12 h-12 text-primary-500 animate-bounce" />
              <p className="text-primary-600 font-semibold mt-3">
                Drop your file here
              </p>
            </div>
          )}

          {!value ? (
            <div className="flex flex-col items-center justify-center gap-3 py-4">
              <div className="p-4 rounded-full bg-default-100">
                <UploadIcon className="w-8 h-8 text-default-500" />
              </div>

              <div className="text-center space-y-1">
                <p className="text-base font-semibold text-default-700">
                  {label}
                </p>
                <p className="text-sm text-default-500">
                  Drag and drop or{" "}
                  <span className="text-primary-500 font-medium">browse</span>
                </p>
                <p className="text-xs text-default-400">
                  {accept === "image/*"
                    ? `PNG, JPG, GIF, WEBP up to ${maxSizeMB}MB`
                    : `Max file size: ${maxSizeMB}MB`}
                </p>
              </div>
            </div>
          ) : (
            <div className="flex items-center justify-between gap-4">
              <div className="flex items-center gap-3 flex-1 min-w-0">
                <div className="p-2 rounded-lg bg-success-100">
                  <ImageIcon className="w-6 h-6 text-success-600" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-default-700 truncate">
                    {displayedName}
                  </p>
                  <p className="text-xs text-default-500">Ready to upload</p>
                </div>
              </div>

              <button
                type="button"
                onClick={handleRemove}
                disabled={isDisabled}
                className="
                  p-2 rounded-lg hover:bg-danger-50 
                  text-danger-500 transition-all
                  hover:scale-110 transform
                  disabled:opacity-50 disabled:cursor-not-allowed
                  flex-shrink-0
                "
                aria-label="Remove file"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
          )}

          <input
            id={id}
            name={id}
            type="file"
            onChange={handleFileChange}
            className="hidden"
            accept={accept}
            disabled={isDisabled}
            aria-describedby={error ? `${id}-error` : undefined}
            {...rest}
          />
        </label>
      </div>

      {error && (
        <div className="flex items-start gap-2 p-3 rounded-lg bg-danger-50 border border-danger-200">
          <svg
            className="w-5 h-5 text-danger-500 flex-shrink-0 mt-0.5"
            fill="currentColor"
            viewBox="0 0 20 20"
          >
            <path
              fillRule="evenodd"
              d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z"
              clipRule="evenodd"
            />
          </svg>
          <p id={`${id}-error`} className="text-sm text-danger-700 font-medium">
            {error}
          </p>
        </div>
      )}

      {showPreview && previewUrl && isImage && (
        <div className="relative rounded-xl overflow-hidden border-2 border-default-200 group">
          <img
            src={previewUrl}
            alt="Preview"
            className="w-full h-64 object-cover"
            loading="lazy"
          />

          <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all duration-300">
            <div className="absolute bottom-0 left-0 right-0 p-4">
              <p className="text-white text-sm font-medium truncate">
                {displayedName}
              </p>
            </div>

            <button
              type="button"
              onClick={handleRemove}
              disabled={isDisabled}
              className="
                absolute top-3 right-3 p-2 rounded-full 
                bg-danger-500 text-white shadow-xl
                hover:bg-danger-600 hover:scale-110
                transform transition-all duration-200
                disabled:opacity-50 disabled:cursor-not-allowed
              "
              aria-label="Remove image"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

FileUpload.propTypes = {
  label: PropTypes.string,
  value: PropTypes.oneOfType([PropTypes.instanceOf(File), PropTypes.object]),
  id: PropTypes.string.isRequired,
  onChange: PropTypes.func.isRequired,
  accept: PropTypes.string,
  isDisabled: PropTypes.bool,
  showPreview: PropTypes.bool,
  maxSizeMB: PropTypes.number,
};

export default FileUpload;
