// components/ExportExcelSelectedDialog.jsx
import { useState } from "react";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
} from "@nextui-org/react";
import * as XLSX from "xlsx";
import { saveAs } from "file-saver"; // Make sure you've installed file-saver

const ExportExcelSelectedDialog = ({
  itemsToExport,
  onClose,
  onExportSuccess,
}) => {
  const [isLoading, setIsLoading] = useState(false);

  const handleExport = () => {
    setIsLoading(true);
    try {
      // Define the order of columns and their headers for the Excel file
      const headers = [
        "Code",
        "Name",
        "Qty",
        "From Unit",
        "To Unit",
        "Total Unit",
        "Selling (MMK)",
        "Purchase (MMK)",
        "Unit",
        "Type",
        "Opening Qty",
        "Purchase Qty",
        "Used Qty",
        "Closing Qty",
        "Branch",
      ];

      // Map your data to match the order of the headers
      const dataForExcel = itemsToExport.map((item) => [
        item.code,
        item.name,
        item.qty,
        item.fromUnit,
        item.toUnit,
        item.totalUnit,
        item.sellingMMK,
        item.purchaseMMK,
        item.unit,
        item.type,
        item.openingQty,
        item.purchaseQty,
        item.usedQty,
        item.closingQty,
        item.branch,
      ]);

      // Add headers as the first row
      const wsData = [headers, ...dataForExcel];

      const ws = XLSX.utils.aoa_to_sheet(wsData);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Selected Inventory");

      // Generate Excel file
      const excelBuffer = XLSX.write(wb, { bookType: "xlsx", type: "array" });
      const data = new Blob([excelBuffer], {
        type: "application/octet-stream",
      });

      saveAs(data, "selected_inventory.xlsx");

      onExportSuccess(itemsToExport); // Pass selected items back for success callback
    } catch (error) {
      console.error("Error exporting Excel file:", error);
      alert("Failed to export Excel file. Please try again.");
    } finally {
      setIsLoading(false);
      onClose(); // Close the dialog whether success or failure
    }
  };

  return (
    <Modal isOpen={true} onClose={onClose}>
      <ModalContent>
        {(onClose) => (
          <>
            <ModalHeader className="flex flex-col gap-1">
              Export Selected Items
            </ModalHeader>
            <ModalBody>
              <p>
                You are about to export <strong>{itemsToExport.length}</strong>{" "}
                selected items to an Excel file.
              </p>
              <p>Do you want to proceed?</p>
            </ModalBody>
            <ModalFooter>
              <Button
                color="danger"
                variant="light"
                onPress={onClose}
                isDisabled={isLoading}
              >
                Cancel
              </Button>
              <Button
                color="primary"
                onPress={handleExport}
                isLoading={isLoading}
                isDisabled={itemsToExport.length === 0}
              >
                {isLoading ? "Exporting..." : "Export"}
              </Button>
            </ModalFooter>
          </>
        )}
      </ModalContent>
    </Modal>
  );
};

export default ExportExcelSelectedDialog;
