import PropTypes from "prop-types";

const AnimateSideText = ({
  condition = true,
  text = "Text",
  className = "",
}) => {
  return (
    <span
      className={`${condition ? "w-[100px] opacity-100" : "w-0 opacity-0"} text-wrap duration-700 transition-all overflow-hidden ${className}`}
    >
      {text}
    </span>
  );
};

AnimateSideText.propTypes = {
  condition: PropTypes.bool,
  text: PropTypes.string,
  className: PropTypes.string,
};

export default AnimateSideText;
