/**
 * Sanitize a string input by trimming whitespace
 * For more robust sanitization, consider using DOMPurify library
 * @param {*} input - Input value to sanitize
 * @returns {*} Sanitized value
 */
export function sanitizeInput(input) {
  if (typeof input === "string") {
    return input.trim();
  }
  return input;
}

/**
 * Sanitize all string values in an object recursively
 * @param {Object} obj - Object to sanitize
 * @returns {Object} Sanitized object
 */
export function sanitizeObject(obj) {
  if (!obj || typeof obj !== "object") {
    return sanitizeInput(obj);
  }

  if (Array.isArray(obj)) {
    return obj.map((item) => sanitizeObject(item));
  }

  const sanitized = {};
  for (const [key, value] of Object.entries(obj)) {
    sanitized[key] =
      typeof value === "object" ? sanitizeObject(value) : sanitizeInput(value);
  }
  return sanitized;
}
